class StreamChecker:
    def __init__(self, words: List[str]):
        self.root = {}
        self.max_len = 0
        for w in words:
            node = self.root
            for ch in reversed(w):           # trie of reversed words
                node = node.setdefault(ch, {})
            node["$"] = True                 # a word ends here
            self.max_len = max(self.max_len, len(w))
        self.stream = []

    def query(self, letter: str) -> bool:
        self.stream.append(letter)
        node = self.root
        stream = self.stream
        # read the stream backwards, newest letter first
        for i in range(len(stream) - 1, max(-1, len(stream) - 1 - self.max_len), -1):
            node = node.get(stream[i])
            if node is None:
                return False
            if "$" in node:
                return True
        return False

