def beautiful_subsets(nums: List[int], k: int) -> int:
    counts = Counter(nums)
    classes = defaultdict(list)
    for v in counts:
        classes[v % k].append(v)
    total = 1
    for values in classes.values():
        values.sort()
        skip, take = 1, 0            # ways where the last value was skipped / taken
        prev = None
        for v in values:
            ways_v = (1 << counts[v]) - 1
            if prev is not None and v - prev == k:
                # cannot take v right after taking v - k
                skip, take = skip + take, skip * ways_v
            else:
                skip, take = skip + take, (skip + take) * ways_v
            prev = v
        total *= skip + take
    return total - 1                 # drop the empty subset

def modified_list(nums: List[int], head: Optional[ListNode]) -> Optional[ListNode]:
    banned = set(nums)
    dummy = ListNode(0, head)
    prev = dummy                       # last node that stays in the list
    while prev.next:
        if prev.next.val in banned:
            prev.next = prev.next.next   # unlink the banned node
        else:
            prev = prev.next
    return dummy.next

def number_of_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 10**9 + 7
    need = {end: cnt for end, cnt in requirements}
    K = need[n - 1]                       # counts above this are useless
    dp = [0] * (K + 1)
    dp[0] = 1                             # prefix of length 1 has no inversions
    if need.get(0, 0) != 0 or any(c > K for c in need.values()):
        return 0                          # a single element has no inversions
    for i in range(1, n):
        # new element adds between 0 and i inversions:
        # new[c] = dp[c - i] + ... + dp[c], a window of prefix sums
        pre = list(itertools.accumulate(dp, initial=0))
        new = [(pre[c + 1] - pre[c - i if c > i else 0]) % MOD for c in range(K + 1)]
        if i in need:
            keep = need[i]
            if keep > K:
                return 0                  # prefix counts can never decrease
            new = [new[c] if c == keep else 0 for c in range(K + 1)]
        dp = new
    return dp[K] % MOD

def longest_continuous_substring(s: str) -> int:
    best = run = 1
    for i in range(1, len(s)):
        if ord(s[i]) == ord(s[i - 1]) + 1:
            run += 1                 # alphabet continues
            if run > best:
                best = run
        else:
            run = 1                  # start a new run here
    return best

