def are_sentences_similar_two(sentence1: List[str], sentence2: List[str],
                              similar_pairs: List[List[str]]) -> bool:
    if len(sentence1) != len(sentence2):
        return False
    parent, size = {}, {}

    def find(w: str) -> str:
        if w not in parent:
            parent[w] = w
            size[w] = 1
        root = w
        while parent[root] != root:
            root = parent[root]
        while parent[w] != root:         # path compression
            parent[w], w = root, parent[w]
        return root

    for x, y in similar_pairs:
        rx, ry = find(x), find(y)
        if rx != ry:
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            size[rx] += size[ry]

    for a, b in zip(sentence1, sentence2):
        if a != b and find(a) != find(b):
            return False
    return True

