def minimum_sum(grid: List[List[int]]) -> int:
    m, n = len(grid), len(grid[0])
    # row_pre[r][c]: ones in row r among columns < c; col_pre[c][r]: ones in column c among rows < r
    row_pre = [[0] * (n + 1) for _ in range(m)]
    for r in range(m):
        for c in range(n):
            row_pre[r][c + 1] = row_pre[r][c] + grid[r][c]
    col_pre = [[0] * (m + 1) for _ in range(n)]
    for c in range(n):
        for r in range(m):
            col_pre[c][r + 1] = col_pre[c][r] + grid[r][c]

    @lru_cache(maxsize=None)
    def box(r1: int, r2: int, c1: int, c2: int) -> int:
        """Area of the bounding box of ones inside rows r1..r2, cols c1..c2 (inclusive)."""
        if r1 > r2 or c1 > c2:
            return 0
        top = r1
        while top <= r2 and row_pre[top][c2 + 1] == row_pre[top][c1]:
            top += 1
        if top > r2:
            return 0                       # no ones in this region
        bottom = r2
        while row_pre[bottom][c2 + 1] == row_pre[bottom][c1]:
            bottom -= 1
        left = c1
        while col_pre[left][r2 + 1] == col_pre[left][r1]:
            left += 1
        right = c2
        while col_pre[right][r2 + 1] == col_pre[right][r1]:
            right -= 1
        return (bottom - top + 1) * (right - left + 1)

    INF = float("inf")
    best = INF
    R, C = m - 1, n - 1
    # three horizontal bands
    for i in range(m - 2):
        for j in range(i + 1, m - 1):
            best = min(best, box(0, i, 0, C) + box(i + 1, j, 0, C) + box(j + 1, R, 0, C))
    # three vertical bands
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            best = min(best, box(0, R, 0, i) + box(0, R, i + 1, j) + box(0, R, j + 1, C))
    for i in range(m - 1):
        for j in range(n - 1):
            # full top band, bottom split left / right
            best = min(best, box(0, i, 0, C) + box(i + 1, R, 0, j) + box(i + 1, R, j + 1, C))
            # top split left / right, full bottom band
            best = min(best, box(0, i, 0, j) + box(0, i, j + 1, C) + box(i + 1, R, 0, C))
            # full left band, right split top / bottom
            best = min(best, box(0, R, 0, j) + box(0, i, j + 1, C) + box(i + 1, R, j + 1, C))
            # left split top / bottom, full right band
            best = min(best, box(0, i, 0, j) + box(i + 1, R, 0, j) + box(0, R, j + 1, C))
    return best

