class Router:
    def __init__(self, memoryLimit: int):
        self.limit = memoryLimit
        self.queue = deque()                    # packets in arrival order
        self.stored = set()                     # triples currently stored
        self.times = defaultdict(list)          # destination -> timestamps in order
        self.start = defaultdict(int)           # destination -> index of first live timestamp

    def _drop_oldest(self) -> List[int]:
        packet = self.queue.popleft()
        self.stored.discard(packet)
        self.start[packet[1]] += 1              # oldest of its destination too
        return list(packet)

    def addPacket(self, source: int, destination: int, timestamp: int) -> bool:
        packet = (source, destination, timestamp)
        if packet in self.stored:
            return False
        if len(self.queue) == self.limit:
            self._drop_oldest()
        self.queue.append(packet)
        self.stored.add(packet)
        self.times[destination].append(timestamp)
        return True

    def forwardPacket(self) -> List[int]:
        if not self.queue:
            return []
        return self._drop_oldest()

    def getCount(self, destination: int, startTime: int, endTime: int) -> int:
        ts = self.times.get(destination)
        if not ts:
            return 0
        lo = self.start[destination]
        left = bisect.bisect_left(ts, startTime, lo)
        right = bisect.bisect_right(ts, endTime, lo)
        return right - left

