def missing_number(arr: list[int]) -> int:
    n = len(arr)
    d = (arr[-1] - arr[0]) // n          # n gaps in the original progression
    if d == 0:
        return arr[0]
    lo, hi = 0, n - 1
    # find the first index whose value is not where the progression puts it
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] == arr[0] + mid * d:
            lo = mid + 1
        else:
            hi = mid
    return arr[0] + lo * d

