def min_cost(n: int, edges: list[list[int]], k: int) -> int:
    if n <= k:
        return 0                       # every node may be its own component
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    components = n
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            components -= 1
            if components <= k:
                return w               # smallest threshold that works
    return 0                           # unreachable for a connected graph

def max_product(s: str) -> int:
    n = len(s)
    full = (1 << n) - 1
    pal = [0] * (1 << n)               # length if the mask spells a palindrome
    for mask in range(1, 1 << n):
        chars = [s[i] for i in range(n) if mask >> i & 1]
        if chars == chars[::-1]:
            pal[mask] = len(chars)
    # best[mask]: longest palindrome using only indices inside mask
    best = pal[:]
    for mask in range(1, 1 << n):
        m = mask
        while m:
            low = m & -m
            sub = best[mask ^ low]
            if sub > best[mask]:
                best[mask] = sub
            m ^= low
    answer = 0
    for a in range(1, 1 << n):
        if pal[a]:
            answer = max(answer, pal[a] * best[full ^ a])
    return answer

