def possibly_equals(s1: str, s2: str) -> bool:
    n, m = len(s1), len(s2)

    @lru_cache(maxsize=None)
    def dfs(i: int, j: int, diff: int) -> bool:
        # diff > 0: s2 is ahead by diff wildcard chars; diff < 0: s1 is ahead.
        # Only the side that is not ahead expands digits, so |diff| <= 999.
        if i == n and j == m:
            return diff == 0
        if diff >= 0 and i < n and s1[i].isdigit():
            value, k = 0, i
            while k < n and s1[k].isdigit():
                value = value * 10 + int(s1[k])
                k += 1
                if dfs(k, j, diff - value):
                    return True
            return False
        if diff <= 0 and j < m and s2[j].isdigit():
            value, k = 0, j
            while k < m and s2[k].isdigit():
                value = value * 10 + int(s2[k])
                k += 1
                if dfs(i, k, diff + value):
                    return True
            return False
        if diff == 0:                          # two letters face each other
            if i < n and j < m and s1[i] == s2[j]:
                return dfs(i + 1, j + 1, 0)
            return False
        if diff > 0:                           # s1 letter fills an s2 wildcard
            return i < n and dfs(i + 1, j, diff - 1)
        return j < m and dfs(i, j + 1, diff + 1)   # s2 letter fills an s1 wildcard

    result = dfs(0, 0, 0)
    dfs.cache_clear()
    return result

class OrderedStream:
    def __init__(self, n: int):
        self.slots = [None] * (n + 2)   # slot 0 unused, slot n + 1 is a sentinel
        self.ptr = 1                    # smallest id not yet released

    def insert(self, idKey: int, value: str) -> list[str]:
        self.slots[idKey] = value
        released = []
        while self.slots[self.ptr] is not None:
            released.append(self.slots[self.ptr])
            self.ptr += 1
        return released

