def find_farmland(land: list[list[int]]) -> list[list[int]]:
    m, n = len(land), len(land[0])
    groups = []
    for r in range(m):
        row = land[r]
        above = land[r - 1] if r > 0 else None
        for c in range(n):
            if row[c] != 1:
                continue
            if (above is not None and above[c] == 1) or (c > 0 and row[c - 1] == 1):
