            r2 = r
            while r2 + 1 < m and land[r2 + 1][c] == 1:
                r2 += 1
            c2 = c
            while c2 + 1 < n and row[c2 + 1] == 1:
                c2 += 1
            groups.append([r, c, r2, c2])
    return groups

