def obj_diff(obj1: Any, obj2: Any) -> dict:
    def kind(v):
        if v is None:
            return "null"
        if isinstance(v, bool):              # must come before the number check
            return "boolean"
        if isinstance(v, (int, float)):
            return "number"
        if isinstance(v, str):
            return "string"
        return "array" if isinstance(v, list) else "object"

    MISSING = object()                       # marker for "no difference"

    def diff(a, b):
        ka, kb = kind(a), kind(b)
        if ka != kb:
            return [a, b]
        if ka not in ("array", "object"):
            return MISSING if a == b else [a, b]
        if ka == "array":
            pairs = [(str(i), a[i], b[i]) for i in range(min(len(a), len(b)))]
        else:
            pairs = [(key, a[key], b[key]) for key in a if key in b]
        out = {}
        for key, x, y in pairs:
            child = diff(x, y)
            if child is not MISSING:
                out[key] = child
        return out if out else MISSING

    result = diff(obj1, obj2)
    return {} if result is MISSING else result

def stone_game_vii(stones: list[int]) -> int:
    n = len(stones)
    pre = [0] * (n + 1)
    for i, s in enumerate(stones):
        pre[i + 1] = pre[i] + s
    dp = [0] * n            # dp[j] = best mover difference on stones i..j
    for i in range(n - 2, -1, -1):
        base_i = pre[i]
        for j in range(i + 1, n):
            take_left = pre[j + 1] - pre[i + 1] - dp[j]        # dp[j] is (i + 1, j)
            take_right = pre[j] - base_i - dp[j - 1]          # dp[j - 1] is (i, j - 1)
            dp[j] = take_left if take_left > take_right else take_right
    return dp[n - 1]

