def num_of_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7
    if k == 0 or k > m:
        return 0                         # first element always costs 1; costs need distinct maxima
    # dp[c][j]: prefixes with search cost c and maximum j
    dp = [[0] * (m + 1) for _ in range(k + 1)]
    for j in range(1, m + 1):
        dp[1][j] = 1
    for _ in range(n - 1):
        new = [[0] * (m + 1) for _ in range(k + 1)]
        for c in range(1, k + 1):
            prev, cur, out = dp[c - 1], dp[c], new[c]
            running = 0                  # sum of prev[j'] for j' < j
            for j in range(1, m + 1):
                out[j] = (cur[j] * j + running) % MOD
                running += prev[j]
        dp = new
    return sum(dp[k]) % MOD

def find_good_strings(n: int, s1: str, s2: str, evil: str) -> int:
    MOD = 10**9 + 7
    L = len(evil)
    # KMP prefix function of evil
    fail = [0] * L
    k = 0
    for i in range(1, L):
        while k and evil[i] != evil[k]:
            k = fail[k - 1]
        if evil[i] == evil[k]:
            k += 1
        fail[i] = k
    # nxt[q][c]: matched length after appending letter c with q already matched
    nxt = [[0] * 26 for _ in range(L)]
    for q in range(L):
        for c in range(26):
            ch = chr(97 + c)
            if evil[q] == ch:
                nxt[q][c] = q + 1
            else:
                nxt[q][c] = nxt[fail[q - 1]][c] if q else 0
    # state: (matched, tight to s1, tight to s2) -> count
    dp = {(0, True, True): 1}
    for i in range(n):
        lo_c, hi_c = ord(s1[i]) - 97, ord(s2[i]) - 97
        new = defaultdict(int)
        for (q, low, high), cnt in dp.items():
            row = nxt[q]
            start = lo_c if low else 0
            end = hi_c if high else 25
            for c in range(start, end + 1):
                nq = row[c]
                if nq == L:
                    continue                      # evil appeared
                key = (nq, low and c == lo_c, high and c == hi_c)
                new[key] = (new[key] + cnt) % MOD
        dp = new
    return sum(dp.values()) % MOD

