def get_words_in_longest_subsequence(words: list[str], groups: list[int]) -> list[str]:
    n = len(words)
    dp = [1] * n
    parent = [-1] * n
    # pattern -> up to two (length, index) chain ends with different groups, best first
    buckets = {}
    for j, w in enumerate(words):
        g = groups[j]
        keys = [w[:p] + "*" + w[p + 1:] for p in range(len(w))]
        for key in keys:
            for length, i in buckets.get(key, ()):
                if groups[i] != g:
                    if length + 1 > dp[j]:
                        dp[j], parent[j] = length + 1, i
                    break                          # best usable entry in this bucket
        for key in keys:
            top = buckets.get(key)
            entry = (dp[j], j)
            if top is None:
                buckets[key] = [entry]
                continue
            # keep the two best entries, and make sure their groups differ
            cand = sorted(top + [entry], key=lambda e: -e[0])
            best = [cand[0]]
            for e in cand[1:]:
                if groups[e[1]] != groups[best[0][1]]:
                    best.append(e)
                    break
            buckets[key] = best
    end = max(range(n), key=lambda i: dp[i])
    chain = []
    while end != -1:
        chain.append(words[end])
        end = parent[end]
    return chain[::-1]

