def number_of_right_triangles(grid: list[list[int]]) -> int:
    rows = [sum(r) for r in grid]
    cols = [sum(c) for c in zip(*grid)]
    total = 0
    for i, row in enumerate(grid):
        extra_row = rows[i] - 1
        if extra_row <= 0:
            continue
        for j, cell in enumerate(row):
            if cell:
                total += extra_row * (cols[j] - 1)   # pick a row partner and a column partner
    return total

def convert_array(nums: list[int]) -> int:
    def nondecreasing_cost(arr: list[int]) -> int:
        heap = []                  # max heap stored as negatives
        cost = 0
        for x in arr:
            heapq.heappush(heap, -x)
            top = -heap[0]
            if top > x:
                cost += top - x    # pull the largest earlier value down to x
                heapq.heapreplace(heap, -x)
        return cost

    return min(nondecreasing_cost(nums), nondecreasing_cost(nums[::-1]))

