def num_rook_captures(board: list[list[str]]) -> int:
    n = len(board)
    # Locate the rook.
    rr = rc = 0
    for r in range(n):
        for c in range(n):
            if board[r][c] == "R":
                rr, rc = r, c
    captures = 0
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        r, c = rr + dr, rc + dc
        # Slide across empty squares.
        while 0 <= r < n and 0 <= c < n and board[r][c] == ".":
            r += dr
            c += dc
        if 0 <= r < n and 0 <= c < n and board[r][c] == "p":
            captures += 1
