def max_target_nodes(edges1: list[list[int]], edges2: list[list[int]], k: int) -> list[int]:
    def reach_counts(edges, limit):
        """For each node, how many nodes are at distance <= limit."""
        size = len(edges) + 1
        if limit < 0:
            return [0] * size
        adj = [[] for _ in range(size)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        counts = []
        for src in range(size):
            # BFS that keeps the parent to avoid a visited array (it is a tree).
            frontier = [(src, -1)]
            total = 1
            depth = 0
            while frontier and depth < limit:
                nxt = []
                for node, parent in frontier:
                    for nb in adj[node]:
                        if nb != parent:
                            nxt.append((nb, node))
                total += len(nxt)
                frontier = nxt
                depth += 1
            counts.append(total)
        return counts

    best_second = max(reach_counts(edges2, k - 1))
    return [c + best_second for c in reach_counts(edges1, k)]

