def find_substring_in_wrapround_string(s: str) -> int:
    longest = [0] * 26          # longest valid run ending in each letter
    run = 0
    prev = -2
    for ch in s:
        cur = ord(ch) - 97
        # Continue the run when cur follows prev in the circular alphabet.
        run = run + 1 if (prev + 1) % 26 == cur else 1
        if run > longest[cur]:
            longest[cur] = run
        prev = cur
    return sum(longest)

