def check(args, got, expected):
    ops, params = args
    radius, xc, yc = params[0]
    if not isinstance(got, list) or len(got) != len(ops) or got[0] is not None:
        return False
    pts = got[1:]
    slack = radius * 1e-7 + 1e-6
    d2 = []
    for p in pts:
        if not isinstance(p, list) or len(p) != 2:
            return False
        x, y = p
        if not all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in (x, y)):
            return False
        dx, dy = x - xc, y - yc
        dist = math.hypot(dx, dy)
        if dist > radius + slack:
            return False
        d2.append((dx, dy, dist))
    c = len(d2)
    if c < 200:
        return True

    def close(hits, prob):
        mean = c * prob
        sd = math.sqrt(c * prob * (1 - prob))
        return abs(hits - mean) <= 4.5 * sd + 2

    # Uniform over the area: P(dist <= r/2) = 1/4, P(dist <= r/sqrt(2)) = 1/2.
    if not close(sum(1 for _, _, d in d2 if d <= radius / 2), 0.25):
        return False
    if not close(sum(1 for _, _, d in d2 if d <= radius / math.sqrt(2)), 0.5):
        return False
    # Each quadrant around the centre holds a quarter of the points.
    for sx in (1, -1):
        for sy in (1, -1):
            if not close(sum(1 for dx, dy, _ in d2 if dx * sx > 0 and dy * sy > 0), 0.25):
                return False
    # Points must not hug the axes more than they should (8 equal angular sectors).
    sectors = Counter(int((math.atan2(dy, dx) + math.pi) / (math.pi / 4)) % 8 for dx, dy, _ in d2)
    for s in range(8):
        if not close(sectors.get(s, 0), 0.125):
            return False
    return True

