def get_factors(n: int) -> list[list[int]]:
    result = []

    def search(rem, lo, path):
        f = lo
        while f * f <= rem:
            if rem % f == 0:
                # rem = f * (rem // f) with rem // f >= f: a finished combination.
                result.append(path + [f, rem // f])
                search(rem // f, f, path + [f])
            f += 1

    search(n, 2, [])
    return result

def longest_ideal_string(s: str, k: int) -> int:
    best = [0] * 26          # longest ideal subsequence ending in each letter
    for ch in s:
        c = ord(ch) - 97
        lo = max(0, c - k)
        hi = min(25, c + k)
        cand = max(best[lo:hi + 1]) + 1
        if cand > best[c]:
            best[c] = cand
    return max(best)

