def lex_smallest_after_deletion(s: str) -> str:
    left = Counter(s)            # copies not yet deleted
    stack = []
    for ch in s:
        # A larger letter before a smaller one should go if it has a spare copy.
        while stack and stack[-1] > ch and left[stack[-1]] > 1:
            left[stack.pop()] -= 1
        stack.append(ch)
    # Trailing duplicates only make the string longer: drop them.
    while stack and left[stack[-1]] > 1:
        left[stack.pop()] -= 1
    return "".join(stack)
